(()=>{'use strict';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],ar=document.documentElement.lang==='ar';
const config=JSON.parse($('#site-config')?.textContent||'{}'),prefix=config.prefix||'';
const whatsapp=$('.whatsapp-fab'),whatsappDialog=$('#whatsapp-contact'),whatsappNumber=String(config.whatsapp||'').replace(/[^0-9]/g,'');
whatsapp?.addEventListener('click',()=>whatsappDialog?.showModal());
whatsappDialog?.addEventListener('close',()=>whatsapp?.focus({preventScroll:true}));
all('[data-whatsapp-open]').forEach(open=>{
 const number=open.dataset.whatsappOpen;
 const product=$('.product-summary h1')?.textContent.trim();
 const message=ar?('السلام عليكم BIOJOUD، أرغب في معلومات'+(product?' حول '+product:' عن منتجاتكم الفلاحية')+'.'):('Bonjour BIOJOUD, je souhaite des informations '+(product?'sur '+product:'sur vos solutions agricoles')+'.');
 open.href='https://wa.me/'+number+'?text='+encodeURIComponent(message);
});
all('[data-copy-whatsapp]').forEach(button=>button.addEventListener('click',async()=>{const number='+'+button.dataset.copyWhatsapp;try{await navigator.clipboard.writeText(number);button.textContent=ar?'تم نسخ الرقم':'Numéro copié';$('#whatsapp-status').textContent=ar?'تم نسخ الرقم':'Numéro copié';}catch{button.textContent=number;}}));
const headerLinks=all('.header-quick a');
const observedSections=headerLinks.map(a=>document.getElementById(new URL(a.href,location.href).hash.slice(1))).filter(Boolean);
if('IntersectionObserver' in window&&observedSections.length){
 const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;headerLinks.forEach(a=>{const current=new URL(a.href,location.href).hash==='#'+entry.target.id;if(current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-15% 0px -55% 0px',threshold:0});observedSections.forEach(section=>observer.observe(section));
}
const menu=$('.menu-toggle'),nav=$('#main-nav');let previousMenuFocus=null;
function setMenu(open){if(!menu||!nav)return;if(open){previousMenuFocus=document.activeElement;nav.inert=false;}menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?(ar?'إغلاق القائمة':'Fermer le menu'):(ar?'فتح القائمة':'Ouvrir le menu'));nav.classList.toggle('open',open);if(!open){nav.inert=true;if(nav.contains(document.activeElement))menu.focus()} }
menu?.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));
all('[data-menu-close],#main-nav a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);if(e.key==='Tab'&&menu?.getAttribute('aria-expanded')==='true'){const focusable=[menu,...all('#main-nav a,#main-nav button')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const catalog=$('.catalog'),cards=all('.catalog [data-card]'),search=$('#product-search'),more=$('#show-all');let filter='Tous',query='',expanded=false;
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
function render(){if(!catalog)return;const matches=cards.filter(card=>(filter==='Tous'||card.dataset.category===filter)&&(!query||norm(card.dataset.search).includes(norm(query))));const browsing=filter==='Tous'&&!query;const limit=window.matchMedia('(max-width:700px)').matches?6:window.matchMedia('(max-width:960px)').matches?8:9;
cards.forEach(c=>c.hidden=true);matches.forEach((card,i)=>card.hidden=browsing&&!expanded&&i>=limit);$('#empty').hidden=matches.length>0;$('#result-count').textContent=matches.length+(ar?' منتجاً':' solution'+(matches.length===1?'':'s')+' à découvrir');more.hidden=!(browsing&&!expanded&&matches.length>limit);all('[data-filter]').forEach(b=>{const on=b.dataset.filter===filter;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});}
all('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;expanded=false;render()}));
document.addEventListener('click',e=>{const a=e.target.closest('[data-category-link]');if(a&&catalog){filter=a.dataset.categoryLink;query='';search.value='';expanded=false;render()}});
search?.addEventListener('input',e=>{query=e.target.value.trim();render()});more?.addEventListener('click',()=>{expanded=true;render()});if(catalog){render();window.matchMedia('(max-width:700px)').addEventListener('change',render);window.matchMedia('(max-width:960px)').addEventListener('change',render)}
const resource=$('#resource-product');resource?.addEventListener('change',()=>$('#resource-download').href=resource.value);
$('#year').textContent=new Date().getFullYear();
// The original labels are independent of the simplified presentation faces.
const labelDialog=$('#label-dialog');let lastLabelTrigger;
document.addEventListener('click',e=>{const b=e.target.closest('[data-label]');if(!b)return;lastLabelTrigger=b;$('#label-title').textContent=b.dataset.name;$('#label-image').src=b.dataset.label;$('#label-image').alt=(ar?'الملصق الأصلي الكامل ':'Étiquette originale complète ')+b.dataset.name;$('#label-pdf').href=b.dataset.pdf;$('.label-scroll').classList.remove('zoomed');$('#label-zoom').setAttribute('aria-pressed','false');$('#label-zoom').textContent=ar?'تكبير +':'Agrandir +';labelDialog.showModal();});
$('#label-zoom')?.addEventListener('click',()=>{const zoom=$('.label-scroll').classList.toggle('zoomed');$('#label-zoom').setAttribute('aria-pressed',String(zoom));$('#label-zoom').textContent=zoom?(ar?'تصغير −':'Réduire −'):(ar?'تكبير +':'Agrandir +')});
all('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));all('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));labelDialog?.addEventListener('close',()=>lastLabelTrigger?.focus({preventScroll:true}));
all('[data-stage]').forEach(b=>b.addEventListener('click',()=>{const label=b.dataset.stage==='label';$('.stage-pack').hidden=label;$('.stage-original').hidden=!label;$('.product-stage>small').textContent=label?(ar?'الملصق الأصلي الكامل':'ÉTIQUETTE ORIGINALE COMPLÈTE'):(ar?'صورة توضيحية للعبوة':'VISUEL DE PRÉSENTATION');all('[data-stage]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))})}));
// Profile panels: accessible keyboard and click navigation.
function showAudience(key){all('[data-audience]').forEach(b=>{const on=b.dataset.audience===key;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;$('#panel-'+b.dataset.audience).hidden=!on})}
all('[data-audience]').forEach((b,i)=>{b.addEventListener('click',()=>showAudience(b.dataset.audience));b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const list=all('[data-audience]');let n=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;showAudience(list[n].dataset.audience);list[n].focus()})});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let productData=[];const selected=new Set();
const catsAr={'Nutrition du sol':'تغذية التربة','Nutrition végétale':'تغذية النبات','Biostimulation':'التحفيز الحيوي','Protection des cultures':'حماية المحاصيل','Adjuvants':'مساعدات التطبيق'};
function updateTray(){const n=selected.size;$('#compare-tray').hidden=n===0;$('#compare-count').textContent=n;$('#compare-open').disabled=n<2;all('[data-compare]').forEach(c=>c.checked=selected.has(+c.dataset.compare));}
all('[data-compare]').forEach(c=>c.addEventListener('change',()=>{const id=+c.dataset.compare;if(c.checked){if(selected.size>=3){c.checked=false;$('#site-status').textContent=ar?'يمكن مقارنة ثلاثة منتجات كحد أقصى.':'Vous pouvez comparer trois produits au maximum.';return}selected.add(id)}else selected.delete(id);updateTray()}));
$('#compare-reset')?.addEventListener('click',()=>{selected.clear();updateTray()});
$('#compare-open')?.addEventListener('click',()=>{if(selected.size<2)return;const list=productData.filter(p=>selected.has(p.id));if(list.length<2)return;const field=(fr,a)=>ar?a:fr;const rows=[
[field('Famille','العائلة'),p=>escape(ar?catsAr[p.cat]:p.cat)],
[field('Conditionnement','حجم العبوة'),p=>escape(p.size)],
[field('Base de la formulation','أساس التركيبة'),p=>escape(p.basis)],
[field('Principaux composants','المكونات الرئيسية'),p=>p.composition.slice(0,4).map(r=>escape(r[0])+': <b>'+escape(r[1])+'</b>').join('<br>')],
[field('Application et dose','الاستعمال والجرعة'),p=>p.uses.map(r=>'<b>'+escape(r[0])+'</b><br>'+escape(r[1])).join('<br><br>')],
[field('Document original','الوثيقة الأصلية'),p=>'<a href="'+prefix+escape(p.pdf)+'" target="_blank" rel="noopener">PDF ↓</a>']
];$('#compare-content').innerHTML='<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th scope="col">BIOJOUD</th>'+list.map(p=>'<td><img src="'+prefix+'assets/packshots-original/'+p.slug+'.webp" alt="'+escape(p.name)+'"><h3>'+escape(p.name)+'</h3><small>'+escape(p.sub)+'</small><a href="'+prefix+(ar?'ar/produits/':'produits/')+p.slug+'.html">'+field('Voir la fiche','شاهد المنتج')+' ↗</a></td>').join('')+'</tr></thead><tbody>'+rows.map(([label,fn])=>'<tr><th scope="row">'+label+'</th>'+list.map(p=>'<td>'+fn(p)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';$('#compare-dialog').showModal()});
function showNeed(cat){if(!$('#need-products'))return;all('[data-need]').forEach(b=>{const on=b.dataset.need===cat;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});const list=productData.filter(p=>p.cat===cat);$('#need-family').textContent=ar?catsAr[cat]:cat;$('#need-count').textContent=list.length+(ar?' منتجات':' solutions');$('#need-all').dataset.categoryLink=cat;const featuredIds=cat==='Nutrition du sol'?[1,21,22]:cat==='Biostimulation'?[16,10,17]:cat==='Nutrition végétale'?[3,2,19]:[5,14,4];const matches=featuredIds.map(id=>list.find(p=>p.id===id)).filter(Boolean);$('#need-products').innerHTML=matches.map(p=>'<a class="finder-product" href="'+(ar?'ar/produits/':'produits/')+p.slug+'.html"><img src="assets/packshots-original/'+p.slug+'.webp" alt="'+escape(p.name)+'" width="65" height="83" loading="lazy"><div><strong>'+escape(p.name)+'</strong><small>'+escape(p.sub)+'</small></div><span>↗</span></a>').join('')}
all('[data-need]').forEach(b=>b.addEventListener('click',()=>showNeed(b.dataset.need)));
fetch(prefix+(ar?'products-ar.json':'products.json')+'?v=12').then(r=>{if(!r.ok)throw Error();return r.json()}).then(p=>{productData=p;showNeed('Nutrition du sol')}).catch(()=>{if($('#need-products'))$('#need-products').innerHTML='<a href="#solutions">'+(ar?'شاهد جميع المنتجات':'Consulter le catalogue complet')+' ↗</a>';$('#compare-open').disabled=true;});
const form=$('#contact-form');if(form){const request=new URLSearchParams(location.search).get('demande');if(request){const option=[...$('#contact-product').options].find(o=>o.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')===request||o.value===request);if(option)$('#contact-product').value=option.value;}
form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);const body='Bonjour BIOJOUD,\n\n'+d.get('message')+'\n\nNom : '+d.get('nom')+'\nE-mail : '+d.get('email')+'\nCulture / activité : '+(d.get('culture')||'Non précisée')+'\nSurface / quantité : '+(d.get('surface')||'Non précisée')+'\nProduit : '+(d.get('produit')||'À conseiller')+'\n\nMerci.';location.href='mailto:biojoudmaroc@gmail.com?subject='+encodeURIComponent('Demande BIOJOUD — '+(d.get('produit')||'Informations'))+'&body='+encodeURIComponent(body);$('#contact-status').textContent=ar?'طلبك جاهز في تطبيق البريد. إذا لم يفتح، راسل biojoudmaroc@gmail.com مباشرة.':'Votre demande est préparée dans votre messagerie. Si elle ne s’ouvre pas, écrivez à biojoudmaroc@gmail.com.'})}
})();
